// Share only pages with their own article or event URL.
(() => {
  const article = document.querySelector('main .article-detail');
  if (!article || !/\/(articles|news|events)\/[a-z0-9-]+\.html$/.test(location.pathname)) return;
  const meta = article.querySelector('.article-meta') || article;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'share-page-button';
  button.textContent = '分享這篇';
  button.setAttribute('aria-label', '分享或複製文章介紹與連結');
  meta.append(button);
  button.addEventListener('click', async () => {
    const url = document.querySelector('link[rel="canonical"]')?.href || location.href;
    const title = document.querySelector('main h1')?.textContent.trim() || document.title;
    const text = `👀 這篇匹克球文章分享給你！\n${title}\n`;
    const copyText = async () => {
      await navigator.clipboard.writeText(`${text}\n${url}`);
      button.textContent = '已複製分享文字';
      setTimeout(() => { button.textContent = '分享這篇'; }, 2500);
    };
    try {
      if (navigator.share) { await navigator.share({title,text,url}); return; }
      await copyText();
    } catch (error) {
      if (error?.name !== 'AbortError') {
        try { await copyText(); }
        catch {
          button.textContent = '請使用瀏覽器分享功能';
          setTimeout(() => { button.textContent = '分享這篇'; }, 3000);
        }
      }
    }
  });
})();

// Shared back-to-top control, with reduced-motion and keyboard support.
(() => {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'back-to-top';
  button.setAttribute('aria-label', '回到頂端');
  button.title = '回到頂端';
  button.innerHTML = '<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M6 14l6-6 6 6M6 5h12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  button.hidden = true;
  document.body.append(button);
  const sync = () => { button.hidden = window.scrollY < 360; };
  window.addEventListener('scroll', sync, { passive: true });
  sync();
  button.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
    const heading = document.querySelector('main h1');
    if (heading) {
      const original = heading.getAttribute('tabindex');
      heading.setAttribute('tabindex', '-1');
      heading.focus({ preventScroll: true });
      heading.addEventListener('blur', () => original === null ? heading.removeAttribute('tabindex') : heading.setAttribute('tabindex', original), { once: true });
    }
  });
})();

(() => {
  const header = document.querySelector('.site-header');
  const toggle = header?.querySelector('.menu-button');
  if (!toggle) return;
  const close = () => { header.classList.remove('open'); toggle.setAttribute('aria-expanded', 'false'); toggle.setAttribute('aria-label', '開啟選單'); };
  toggle.addEventListener('click', () => toggle.setAttribute('aria-label', header.classList.contains('open') ? '關閉選單' : '開啟選單'));
  document.addEventListener('keydown', event => { if (event.key === 'Escape' && header.classList.contains('open')) { close(); toggle.focus(); } });
  document.addEventListener('click', event => { if (!header.contains(event.target)) close(); });
})();

// Listing view preference survives searching, filtering and pagination.
(() => {
 const list=document.querySelector('#article-list, #news-page-list, #event-list');
 const toolbar=document.querySelector('[data-listing-view-controls]');
 if(!list||!toolbar)return;
 const key='hlpb-view-'+list.id;
 const buttons=[...toolbar.querySelectorAll('[data-listing-view]')];
 let initial='grid';try{if(localStorage.getItem(key)==='list')initial='list'}catch(e){}
 const select=view=>{list.dataset.view=view;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.listingView===view)));try{localStorage.setItem(key,view)}catch(e){}};
 buttons.forEach(b=>b.addEventListener('click',()=>select(b.dataset.listingView)));
 const sync=()=>{toolbar.hidden=list.hidden};
 new MutationObserver(sync).observe(list,{attributes:true,attributeFilter:['hidden']});
 select(initial);sync();
})();

// Keep the About HLPB footer entry consistent on every page.
(() => {
  document.querySelectorAll('.footer-map > div:first-child').forEach(nav => {
    if (nav.querySelector('[data-about-link]')) return;
    const link = document.createElement('a');
    link.dataset.aboutLink = 'true';
    // The footer brand always points to index.html in the site root.
    link.href = new URL('about.html', document.querySelector('.site-footer .brand').href).href;
    link.textContent = '關於 HLPB';
    const heading = nav.querySelector('h3');
    if (heading) heading.after(link); else nav.prepend(link);
  });
})();

// Consistent section entrances, without replaying the initial viewport.
(() => {
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 if(!('IntersectionObserver' in window)||!Element.prototype.animate)return;
 const seen=new WeakSet();
 const selector='main>section,main>article,main>.article-list>.article-card,main>.event-list>.event';
 const observer=new IntersectionObserver(entries=>{
  entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top).forEach(({target},i)=>{
   observer.unobserve(target);if(reduced.matches)return;
   target.animate([{opacity:.65,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,delay:Math.min(i*35,105),easing:'ease-out'});
  });
 },{threshold:.08});
 let queued=false;
 const scan=()=>{queued=false;document.querySelectorAll(selector).forEach(el=>{if(seen.has(el))return;seen.add(el);if(el.getBoundingClientRect().top<innerHeight)return;if(el.parentElement.closest(selector))return;observer.observe(el)})};
 const main=document.querySelector('main');if(main)new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(scan)}}).observe(main,{childList:true,subtree:true});
 reduced.addEventListener('change',()=>{if(reduced.matches)document.querySelectorAll(selector).forEach(el=>el.getAnimations().forEach(a=>a.cancel()))});scan();
})();

// Site-wide sharing and home-screen shortcut help. No app or offline cache.
(() => {
  const footer = document.querySelector('.site-footer');
  if (!footer || document.querySelector('.site-quick-actions')) return;
  let installPrompt;
  window.addEventListener('beforeinstallprompt', event => { event.preventDefault(); installPrompt = event; });
  window.addEventListener('appinstalled', () => { installPrompt = null; });
  const styles = document.createElement('style');
  styles.textContent = `.site-quick-actions{display:flex;flex-wrap:wrap;gap:12px;box-sizing:border-box;width:calc(100% - 48px);max-width:1180px;padding:24px 0;margin:0 auto 24px;border-bottom:1px solid #657b83}.site-quick-actions button{font:inherit;font-weight:700;min-height:48px;padding:12px 20px;background:#f5c451;color:#142e40;border:2px solid #f5c451;border-radius:6px;cursor:pointer}.site-quick-actions button:last-child{background:transparent;color:#fff;border-color:#a9c4bd}.site-quick-actions button:focus-visible,.site-action-dialog button:focus-visible{outline:3px solid #63b7a8;outline-offset:4px}.site-action-dialog{box-sizing:border-box;width:min(520px,calc(100% - 32px));max-height:85vh;overflow:auto;padding:28px;border:2px solid #142e40;border-radius:12px;background:#f7f1e5;color:#142e40}.site-action-dialog::backdrop{background:#142e4099}.site-action-dialog h2{font-size:1.4rem;margin:0 0 16px}.site-action-dialog p{line-height:1.7}.site-action-dialog button{font:inherit;font-weight:700;padding:12px 20px;border:0;border-radius:5px;background:#26756e;color:white;min-height:44px;cursor:pointer}.site-action-dialog textarea{box-sizing:border-box;width:100%;min-height:140px;padding:12px;font:inherit;line-height:1.6;background:white;color:#142e40;border:1px solid #647879}@media(max-width:600px){.site-quick-actions{flex-direction:column}.site-quick-actions button{width:100%}}`;
  document.head.append(styles);
  const actions = document.createElement('div');
  actions.className = 'site-quick-actions';
  actions.setAttribute('aria-label', '分享與加入主畫面');
  const share = document.createElement('button'); share.type = 'button'; share.textContent = '分享這個頁面 ↗';
  const home = document.createElement('button'); home.type = 'button'; home.textContent = '加入手機主畫面 ＋';
  actions.append(share, home); (footer.querySelector('.footer-about') || footer).append(actions);
  function showDialog(title, paragraphs, copy) {
    const dialog = document.createElement('dialog'); dialog.className = 'site-action-dialog';
    const heading = document.createElement('h2'); heading.id = 'site-action-title'; heading.textContent = title;
    dialog.setAttribute('aria-labelledby', heading.id); dialog.append(heading);
    paragraphs.forEach(value => { const p = document.createElement('p'); p.textContent = value; dialog.append(p); });
    if (copy) { const field = document.createElement('textarea'); field.readOnly = true; field.value = copy; field.setAttribute('aria-label', '網站分享文字，請選取後複製'); dialog.append(field); }
    const close = document.createElement('button'); close.type = 'button'; close.textContent = '知道了'; close.addEventListener('click', () => dialog.close()); dialog.append(close);
    const previous = document.activeElement;
    dialog.addEventListener('close', () => { dialog.remove(); previous?.focus(); });
    document.body.append(dialog); dialog.showModal();
  }
  share.textContent='分享這個頁面 ↗';
  share.addEventListener('click', async () => {
    const title=window.HLPB_PAGE_SHARE?.title||document.querySelector('meta[property=\"og:title\"]')?.content||document.title;
    const summary=window.HLPB_PAGE_SHARE?.description||document.querySelector('meta[name=\"description\"]')?.content||'';
    const text='👀 這個匹克球頁面分享給你！\n'+title+'\n'+summary;
    const url=window.HLPB_PAGE_SHARE?.url||document.querySelector('link[rel=canonical]')?.href||location.href;
    try { if (navigator.share) { await navigator.share({ title, text, url }); return; } }
    catch (error) { if (error?.name === 'AbortError') return; }
    const copy = `${text}\n${url}`;
    try { await navigator.clipboard.writeText(copy); share.textContent = '已複製頁面介紹與連結'; setTimeout(() => { share.textContent = '分享這個頁面 ↗'; }, 3000); }
    catch { showDialog('分享網站給朋友', ['請選取以下文字並複製，貼給朋友就能分享。'], copy); }
  });
  home.addEventListener('click', async () => {
    if (window.matchMedia('(display-mode: standalone)').matches || navigator.standalone) { showDialog('已從主畫面開啟', ['你目前已使用主畫面入口開啟 HLPB。']); return; }
    if (installPrompt) {
      const prompt = installPrompt; installPrompt = null;
      try { await prompt.prompt(); await prompt.userChoice; return; } catch { /* Show manual steps when prompting is unavailable. */ }
    }
    showDialog('加入手機主畫面', [
      'Android：請用 Chrome 或 Brave 開啟 HLPB，點瀏覽器選單「⋮」，選擇「加入主畫面」或「新增至主畫面」，再確認新增。選項名稱依瀏覽器版本而異。',
      'iPhone：請用 Safari 開啟 HLPB，點「分享」，選擇「加入主畫面」，再點「新增」。',
      '如果你在 LINE、Facebook 或其他 App 內瀏覽，請先選「在外部瀏覽器開啟」。這是網站的快捷入口，不需要下載 Android App。'
    ]);
  });
})();

